import { cn } from '@/lib/utils';

interface HeaderProps extends React.HTMLAttributes<HTMLElement> {
  ref?: React.Ref<HTMLElement>;
  fullWidth?: boolean;
}

interface HeaderContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  ref?: React.Ref<HTMLDivElement>;
  fullWidth?: boolean;
}

interface HeaderLogoProps extends React.HTMLAttributes<HTMLDivElement> {
  ref?: React.Ref<HTMLDivElement>;
}

interface HeaderLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  ref?: React.Ref<HTMLAnchorElement>;
}

interface HeaderServiceNameProps
  extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  ref?: React.Ref<HTMLAnchorElement>;
}

interface HeaderNavProps extends React.HTMLAttributes<HTMLElement> {
  ref?: React.Ref<HTMLElement>;
}

interface HeaderNavItemProps
  extends React.LiHTMLAttributes<HTMLLIElement> {
  ref?: React.Ref<HTMLLIElement>;
  active?: boolean;
}

interface HeaderNavLinkProps
  extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  ref?: React.Ref<HTMLAnchorElement>;
}

const Header = ({
  className,
  children,
  fullWidth,
  ref,
  ...props
}: HeaderProps) => (
  <header
    ref={ref}
    className={cn(
      'font-govuk text-govuk-header',
      'border-b border-b-transparent',
      'text-white bg-govuk-brand',
      className,
    )}
    {...props}
  >
    {children ?? (
      <HeaderContainer fullWidth={fullWidth}>
        <HeaderLogo />
      </HeaderContainer>
    )}
  </header>
);

const HeaderContainer = ({
  className,
  fullWidth,
  ref,
  ...props
}: HeaderContainerProps) => (
  <div
    ref={ref}
    className={cn(
      'flex items-center flex-wrap',
      fullWidth ? 'px-govuk-3' : 'max-w-240 mx-auto px-govuk-3',
      className,
    )}
    {...props}
  />
);

const HeaderLogo = ({ className, ref, ...props }: HeaderLogoProps) => (
  <div
    ref={ref}
    className={cn(
      'box-border py-govuk-2 mr-govuk-2',
      className,
    )}
    {...props}
  />
);

const HeaderLink = ({ className, ref, ...props }: HeaderLinkProps) => (
  <a
    ref={ref}
    className={cn(
      'inline-flex items-center text-govuk-header-link no-underline text-white',
      'visited:text-white active:text-white',
      'hover:underline hover:govuk-link-underline hover:govuk-link-underline-hover',
      'focus:govuk-link-focus',
      'focus:not-focus:bg-govuk-brand',
      className,
    )}
    {...props}
  />
);

const HeaderServiceName = ({
  className,
  ref,
  ...props
}: HeaderServiceNameProps) => (
  <a
    ref={ref}
    className={cn(
      'inline-flex items-center text-govuk-body font-bold no-underline text-white',
      'py-govuk-2 mr-govuk-2',
      'visited:text-white active:text-white',
      'hover:underline hover:govuk-link-underline hover:govuk-link-underline-hover',
      'focus:govuk-link-focus',
      'focus:not-focus:bg-govuk-brand',
      className,
    )}
    {...props}
  />
);

const HeaderNav = ({ className, ref, children, ...props }: HeaderNavProps) => (
  <nav
    ref={ref}
    className={cn('ml-auto', className)}
    {...props}
  >
    <ul className='flex items-center gap-govuk-4 list-none m-0 p-0'>
      {children}
    </ul>
  </nav>
);

const HeaderNavItem = ({
  className,
  active,
  ref,
  ...props
}: HeaderNavItemProps) => (
  <li
    ref={ref}
    className={cn(
      'py-govuk-2',
      active && 'border-b-govuk-1 border-b-white -mb-px',
      className,
    )}
    {...props}
  />
);

const HeaderNavLink = ({ className, ref, ...props }: HeaderNavLinkProps) => (
  <a
    ref={ref}
    className={cn(
      'text-govuk-body font-bold no-underline text-white',
      'visited:text-white active:text-white',
      'hover:underline hover:govuk-link-underline hover:govuk-link-underline-hover',
      'focus:govuk-link-focus',
      'focus:not-focus:bg-govuk-brand',
      className,
    )}
    {...props}
  />
);

export {
  Header,
  HeaderContainer,
  HeaderLogo,
  HeaderLink,
  HeaderServiceName,
  HeaderNav,
  HeaderNavItem,
  HeaderNavLink,
  type HeaderProps,
  type HeaderContainerProps,
  type HeaderLogoProps,
  type HeaderLinkProps,
  type HeaderServiceNameProps,
  type HeaderNavProps,
  type HeaderNavItemProps,
  type HeaderNavLinkProps,
};
